double _readWebFloat64(
  StructReader reader,
  int offset, {
  double defaultValue = 0.0,
}) {
  final bits = ByteData(8)..setFloat64(0, defaultValue, Endian.little);
  for (var word = 0; word < 8; word += 4) {
    bits.setUint32(
      word,
      reader.getUint32Field(offset + word) ^
          bits.getUint32(word, Endian.little),
      Endian.little,
    );
  }
  return bits.getFloat64(0, Endian.little);
}

void _writeWebFloat64(
  StructBuilder builder,
  int offset,
  double value, {
  double defaultValue = 0.0,
}) {
  final bits = ByteData(8)..setFloat64(0, value, Endian.little);
  final mask = ByteData(8)..setFloat64(0, defaultValue, Endian.little);
  for (var word = 0; word < 8; word += 4) {
    builder.setUint32Field(
      offset + word,
      bits.getUint32(word, Endian.little) ^ mask.getUint32(word, Endian.little),
    );
  }
}

int _checkedWireInt(BigInt value) {
  final signed = value.toSigned(64);
  if (signed.abs() > BigInt.from(9007199254740991)) {
    throw RangeError('Use the BigInt field for an exact 64-bit value');
  }
  return signed.toInt();
}

